import { useToggle } from '@rocket.chat/fuselage-hooks';
import { styled, View } from '@tamagui/web';
import { useId, type KeyboardEvent, type MouseEvent, type ReactNode } from 'react';

import { cx, cxx } from '../../helpers/composeClassNames';
import { StylingBox } from '../Box';
import { Chevron } from '../Chevron';

// generated by scripts/generate-frame-values.mts from @rocket.chat/fuselage-tokens, do not edit

const barLayout = {
	minHeight: '5.5rem',
	paddingBlock: 'calc(32px - 1px)',
	paddingInline: 'calc(8px - 1px)',
	textAlign: 'start',
	borderWidth: '1px',
	borderTopColor: 'var(--rcx-color-stroke-extra-light, #ebecef)',
	borderRightColor: 'transparent',
	borderBottomColor: 'transparent',
	borderLeftColor: 'transparent',
} as const;

const barPlain = {
	color: 'var(--rcx-color-font-titles-labels, #1f2329)',
} as const;

const barInteractive = {
	color: 'var(--rcx-color-font-titles-labels, #1f2329)',
	cursor: 'pointer',
	outlineStyle: 'none',
	backgroundColor: {
		hover: 'var(--rcx-color-surface-tint, #f7f8fa)',
	},
	borderTopColor: {
		default: 'var(--rcx-color-stroke-extra-light, #ebecef)',
		focus: 'var(--rcx-color-stroke-highlight, #156ff5)',
	},
	borderRightColor: {
		default: 'transparent',
		focus: 'var(--rcx-color-stroke-highlight, #156ff5)',
	},
	borderBottomColor: {
		default: 'transparent',
		focus: 'var(--rcx-color-stroke-highlight, #156ff5)',
	},
	borderLeftColor: {
		default: 'transparent',
		focus: 'var(--rcx-color-stroke-highlight, #156ff5)',
	},
	boxShadow: {
		focus: '0 0 0 2px var(--rcx-color-stroke-extra-light-highlight, #d1ebfe)',
	},
} as const;

const barDisabled = {
	color: 'var(--rcx-color-font-disabled, #cbced1)',
	cursor: 'not-allowed',
	backgroundColor: 'var(--rcx-color-surface-disabled, #f7f8fa)',
} as const;

const titleLine = {
	flexGrow: 1,
	flexShrink: 1,
	flexBasis: '0px',
	minWidth: 'auto',
	minHeight: 'auto',
	overflow: 'hidden',
	textOverflow: 'ellipsis',
	whiteSpace: 'nowrap',
	fontSize: '1rem',
	fontWeight: 700,
	lineHeight: '1.5rem',
	letterSpacing: '0rem',
} as const;

const panelCollapsed = {
	visibility: 'hidden',
	height: '0px',
	paddingBlock: 0,
	paddingInline: '8px',
} as const;

const panelExpanded = {
	visibility: 'visible',
	height: 'auto',
	paddingBlock: '32px',
	paddingInline: '8px',
} as const;

// end of generated

// Declared where they render: zero-runtime only erases a `styled()` whose every use is in its own module
const itemLayout = {
	display: 'flex',
	flexDirection: 'column',
	flexWrap: 'nowrap',
	alignItems: 'normal',
	flexShrink: 1,
	minWidth: 'auto',
	minHeight: 'auto',
} as const;

const SectionFrame = styled(View, { render: 'section', ...itemLayout });

const BarFrame = styled(View, {
	render: 'div',
	...itemLayout,
	flexDirection: 'row',
	...barLayout,
	variants: {
		// A bar without a tab stop is not interactive: the one of a noncollapsible item or a disabled one
		state: {
			plain: { ...barPlain },
			interactive: { ...barInteractive },
			disabled: { ...barDisabled },
		},
	},
});

const TitleFrame = styled(View, {
	render: 'h2',
	display: 'block',
	flexDirection: 'row',
	alignItems: 'normal',
	...titleLine,
});

const PanelFrame = styled(View, {
	render: 'div',
	display: 'block',
	flexDirection: 'row',
	alignItems: 'normal',
	flexShrink: 1,
	minWidth: 'auto',
	minHeight: 'auto',
	overflow: 'hidden',
	variants: {
		expanded: {
			true: { ...panelExpanded },
			false: { ...panelCollapsed },
		},
	},
});

export type AccordionItemProps = {
	children?: ReactNode;
	className?: string;
	defaultExpanded?: boolean;
	disabled?: boolean;
	expanded?: boolean;
	tabIndex?: number;
	title: ReactNode;
	noncollapsible?: boolean;
};

const AccordionItem = ({
	children,
	defaultExpanded,
	disabled = false,
	expanded: propExpanded,
	tabIndex = 0,
	title,
	noncollapsible = !title,
	...props
}: AccordionItemProps) => {
	const [stateExpanded, toggleStateExpanded] = useToggle(defaultExpanded);
	const expanded = propExpanded || stateExpanded;

	const panelExpanded = noncollapsible || expanded;

	const titleId = useId();
	const panelId = useId();

	const handleClick = (e: MouseEvent<HTMLElement>) => {
		if (disabled) {
			return;
		}
		e.currentTarget?.blur();
		toggleStateExpanded();
	};

	const handleKeyDown = (event: KeyboardEvent) => {
		if (disabled || event.currentTarget !== event.target) {
			return;
		}

		if (![' ', 'Enter'].includes(event.key)) {
			return;
		}

		event.preventDefault();

		if (event.repeat) {
			return;
		}

		toggleStateExpanded();
	};

	const collapsibleProps = {
		'aria-controls': panelId,
		'aria-expanded': expanded ? 'true' : 'false',
		'tabIndex': !disabled ? tabIndex : undefined,
		'onClick': handleClick,
		'onKeyDown': handleKeyDown,
	} as const;

	const nonCollapsibleProps = {
		'aria-disabled': 'true',
		'aria-expanded': 'true',
		'aria-labelledby': titleId,
	} as const;

	const barProps = noncollapsible ? nonCollapsibleProps : collapsibleProps;

	const barState = [disabled && 'disabled', noncollapsible && 'plain'].find(Boolean) || 'interactive';

	return (
		<StylingBox {...props}>
			<SectionFrame className={cx(cxx('rcx-box')('full'), 'rcx-accordion-item')}>
				{title && (
					<BarFrame
						render={<div role='button' {...barProps} />}
						state={barState}
						className={cx(cxx('rcx-box')('full', 'animated'), cxx('rcx-accordion-item__bar')({ disabled }))}
					>
						<TitleFrame id={titleId} className={cx(cxx('rcx-box')('full'), 'rcx-accordion-item__title')}>
							{title}
						</TitleFrame>
						{!noncollapsible && <Chevron size='x24' up={expanded} />}
					</BarFrame>
				)}
				<PanelFrame
					id={panelId}
					expanded={Boolean(panelExpanded)}
					className={cx(cxx('rcx-box')('full', 'animated'), cxx('rcx-accordion-item__panel')({ expanded: panelExpanded }))}
				>
					{children}
				</PanelFrame>
			</SectionFrame>
		</StylingBox>
	);
};

export default AccordionItem;
